/**
 * The author's first displayed group as a text badge ("Moderator"), from the
 * groups the post payload already includes. Members-only users get none.
 */
export default function groupBadge(user) {
  const groups = (user?.groups?.() || []).filter(g => g && !g.isHidden?.() && g.nameSingular?.());
  const group = groups[0];
  if (!group) return null;
  return m("span", {
    className: "MastheadGroupBadge",
    style: group.color() ? {
      '--mh-tag': group.color()
    } : undefined
  }, group.nameSingular());
}
flarum.reg.add('ernestdefoe-masthead', 'forum/topic/groupBadge', groupBadge);